  return (
    <BaseUIPanel
      {...props}
      keepMounted={keepMounted ?? root.keepMounted}
      hiddenUntilFound={hiddenUntilFound ?? root.hiddenUntilFound}
      component={AccordionPrimitive.Panel}
      open={open}
      sizeVars={['--accordion-panel-height', '--accordion-panel-width']}
    />
  );
}

