import { useInputSwap } from '../../../internal/value-swap';
import {
  CHIP_EXIT_TRANSITION,
  CHIP_SCALE,
  CHIP_TRANSITION,
  PLACEHOLDER_TRANSITION,
  REFLOW_STYLE,
  REFLOW_TRANSITION,
  useReflow,
  type Reflow,
} from '../../../internal/reflow';
import {
  IndicatorMotion,
  useHighlightedItem,
  usePopupRender,
