function useTimingVariables(
  transition: Transition | undefined,
  exitTransition: Transition | undefined,
  fallback: Transition,
  exitFallback?: Transition,
): React.CSSProperties {
  const timings = useModalTransitions(
    transition,
    exitTransition,
    fallback,
    exitFallback,
