function assignRef<T>(ref: React.Ref<T> | undefined, node: T | null) {
  if (typeof ref === 'function') return ref(node);
  if (ref) (ref as React.RefObject<T | null>).current = node;
  return undefined;
}

function findBackdrop(popup: HTMLElement) {
