type Leaving = {
  element: HTMLElement;
  menu: string | null;
  box: DOMRect;
  opacity: number;
  slide: [number, number];
  to: [number, number];
};

function leavingIn(popover: HTMLElement): Leaving[] {
  const found: Leaving[] = [];
  for (const element of Array.from(popover.children)) {
    if (!(element instanceof HTMLElement) || !element.hasAttribute(LAYER))
