    parseFloat(style.height) +
      sum(
        'padding-top',
        'padding-bottom',
        'border-top-width',
        'border-bottom-width',
      ) || el.offsetHeight;
  return {
    x: width ? rect.width / width : 1,
    y: height ? rect.height / height : 1,
  };
