function forget(content: Element[]) {
  for (const el of content) {
    for (const target of [el, ...Array.from(el.querySelectorAll(SHAPES))]) {
      const d = drawn.get(target);
      if (!d) continue;
      d.controls?.stop();
      d.unsubscribe();
      write(target as Styled, d, 1);
      drawn.delete(target);
